messages.body_plain:
Hi,
I am trying to use autodiff::gradient  to extract gradient functions (individually) for my model,  but I am having some difficulty coding it.

Below is my C++ code which doesn't compile in R due to errors arising from type conversion. I have highlighted the functor for the gradient. I would appreciate any help regarding this.

#include <TMB.hpp>

template <class Type>
Type cumhaz(vector<Type> Qpartition, Type survt_1, Type h1, Type h2, Type h3, Type h4, Type h5, Type h6, Type h7, Type h8, Type h9, Type h10, vector<Type> cumhaz_int,
            Type index){

  vector<Type> htilde(10);
  htilde(0)=h1;
  htilde(1)=h2;
  htilde(2)=h3;
  htilde(3)=h4;
  htilde(4)=h5;
  htilde(5)=h6;
  htilde(6)=h7;
  htilde(7)=h8;
  htilde(8)=h9;
  htilde(9)=h10;
  vector<Type> H = cumhaz_int * htilde;
  Type retval = 0;
  if (index == 0){
    retval = H(0);}
  if (index == 1){
    retval = H(0) + H(1);}
  if (index == 2){
    retval = H(0) + H(1) + H(2);}

  if (index == 3){
    retval = H(0) + H(1) + H(2) + H(3);}

  if (index == 4){
    retval = H(0) + H(1) + H(2) + H(3) + H(4);}

  if (index == 5){
    retval = H(0) + H(1) + H(2) + H(3) + H(4) + H(5);}

  if (index == 6){
    retval = H(0) + H(1) + H(2) + H(3) + H(4) + H(5) + H(6);}

  if (index == 7){
    retval = H(0) + H(1) + H(2) + H(3) + H(4) + H(5) + H(6) + H(7);}

  if (index == 8){
    retval = H(0) + H(1) + H(2) + H(3) + H(4) + H(5) + H(6) + H(7) + H(8);}

  if (index == 9){
    retval = H(0) + H(1) + H(2) + H(3) + H(4) + H(5) + H(6) + H(7) + H(8) + H(9);}

  return retval;}

// Likelihood for the survival submodel
template <class Type>
Type llc(Type zeta1, Type h1, Type h2, Type h3, Type h4, Type h5, Type h6, Type h7, Type h8, Type h9, Type h10, Type survt_1, Type di_1, vector<Type> Qpartition, vector<Type> cumhaz_int,
         Type index){
  Type lik_c = 0;
  Type basehaz = 0;

  if(survt_1 <= Qpartition(1)){
    basehaz = h1;}
  if(survt_1 > Qpartition(1) && survt_1 <= Qpartition(2)){
    basehaz = h2;}
  if(survt_1 > Qpartition(2) && survt_1 <= Qpartition(3)){
    basehaz = h3;}

  if(survt_1 > Qpartition(3) && survt_1 <= Qpartition(4)){
    basehaz = h4;}
  if(survt_1 > Qpartition(4) && survt_1 <= Qpartition(5)){
    basehaz = h5;}

  if(survt_1 > Qpartition(5) && survt_1 <= Qpartition(6)){
    basehaz = h6;}
  if(survt_1 > Qpartition(6) && survt_1 <= Qpartition(7)){
    basehaz = h7;}

  if(survt_1 > Qpartition(7) && survt_1 <= Qpartition(8)){
    basehaz = h8;}

  if(survt_1 > Qpartition(8) && survt_1 <= Qpartition(9)){
    basehaz = h9;}

  if(survt_1 > Qpartition(9) && survt_1 <= Qpartition(10)){
    basehaz = h10;}

  lik_c = di_1 * (log(basehaz) + zeta1) - cumhaz(Qpartition, survt_1, h1,h2,h3,h4,h5,h6,h7,h8,h9,h10,cumhaz_int,index) * exp(zeta1);
  return lik_c;  }

template<class Type>
struct func {
  Type zeta1;
  Type h1;
  Type h2;
  Type h3;
  Type h4;
  Type h5;
  Type h6;
  Type h7;
  Type h8;
  Type h9;
  Type h10;
  Type index;
  Type survt_1;
  Type di_1;
  Type w;
  vector<Type> Qpartition;
  vector<Type> cumhaz_int;

  func(Type zeta1_,
       Type h1_,
       Type h2_,
       Type h3_,
       Type h4_,
       Type h5_,
       Type h6_,
       Type h7_,
       Type h8_,
       Type h9_,
       Type h10_,
       Type index_,
       Type survt_1_,
       Type di_1_,
       Type w_,
       vector<Type> Qpartition_,
       vector<Type> cumhaz_int_) :
    zeta1(zeta1_), h1(h1_), h2(h2_), h3(h3_), h4(h4_), h5(h5_),
    h6(h6_), h7(h7_), h8(h8_), h9(h9_), h10(h10_), survt_1(survt_1_),
    di_1(di_1_), w(w_), Qpartition(Qpartition_), cumhaz_int(cumhaz_int_) {}

  template <class T>
  T operator()(vector<T> theta){  // Evaluate function

    return llc(zeta1,h1,h2,h3,h4,h5,h6,h7,h8,h9,h10,survt_1,di_1,Qpartition, cumhaz_int,index) ;
  }
};

// Joint likelihood
template<class Type>
Type objective_function<Type>::operator() ()
{

  /* Data */
  DATA_VECTOR(a1);
  DATA_VECTOR(b1);
  DATA_MATRIX(Z0);
  DATA_INTEGER(N);
  DATA_VECTOR(Qpartition);
  DATA_VECTOR(survt1);
  DATA_VECTOR(di1);
  DATA_VECTOR(cumhaz_int);
  DATA_VECTOR(index_vec);
  DATA_VECTOR(weights);

  /* Parameters */

  PARAMETER_VECTOR(theta);

  /* Joint likelihood */

  Type jnll = Type(0.0);
  Type h1 = theta(0);
  Type h2 = theta(1);
  Type h3 = theta(2);
  Type h4 = theta(3);
  Type h5 = theta(4);
  Type h6 = theta(5);
  Type h7 = theta(6);
  Type h8 = theta(7);
  Type h9 = theta(8);
  Type h10 = theta(9);
  Type lambda2 = theta(10);
  Type lambda3 = theta(11);
  int theta_size = theta.size();
  int gamma_size = theta_size - 12;
  vector<Type> gamma = theta.segment(12,gamma_size);

  vector<Type> zeta = Z0 * gamma + lambda2*a1 + lambda3*b1;
  matrix<Type> g(N,theta_size);
  //the joint negative log-likelihood
  for(int i=0; i<N; i++){

    Type index = index_vec(i);
    Type survt_1 = survt1(i);
    Type di_1 = di1(i);
    Type zeta1 = zeta(i);
    Type w = weights(i);

    //func grad;
    func<Type> f(zeta1,h1, h2, h3, h4, h5, h6, h7, h8, h9, h10, index,survt_1,di_1,w,Qpartition,cumhaz_int);

    jnll -= llc(zeta1,h1,h2,h3,h4,h5,h6,h7,h8,h9,h10,survt_1,di_1,Qpartition, cumhaz_int, index);

    g.row(i) = autodiff::gradient(f, theta);
  }
  ADREPORT(g)
  return jnll;
}

The doxygen help page of 'gradient' should lead to the example
https://github.com/kaskr/adcomp/blob/92c59970843c03488e7d5fdca053ec795eba3f5d/tmb_examples/laplace.cpp#L38-L86
which is fairly close to what you are trying to do in your struct 'func'.
The func evaluation operator needs to apply the conversions, something like:

    T zeta1 = T(this->zeta1); // constant
    T h1 = theta(0); // variable
    T h2 = theta(1); // variable
    vector<T> Qpartition = this->Qpartition.template cast<T>(); // constant

etc., to mention a few of them.

As an unrelated comment, your code could be greatly simplified and generalized (e.g. using cumsum?). And you should be aware of the effect of parameter dependent branching, which may or may not be an issue in your case.

